import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

public class MemoryOverflowToDiskTest {

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	public void testCleanerRemovesTempDirWhenMemoryOverflowModelGetsGCed() throws Exception {
		String output = NativeMemoryOverflowMigrationTest.runInConstrainedHeap("cleaner-gc");
		assertThat(output).contains("CLEANER_SPILL_ADOPTED=true", "CLEANER_GC_COLLECTED=true",
				"CLEANER_DIRECTORY_DELETED=true", "CLEANER_STORE_CLOSE_COUNT=1");
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	public void testExplicitCloseAfterCompletedSpillRemovesTempDirOnce() throws Exception {
		String output = NativeMemoryOverflowMigrationTest.runInConstrainedHeap("cleaner-explicit-close");
		assertThat(output).contains("CLEANER_SPILL_ADOPTED=true", "CLEANER_EXPLICIT_CLOSE_REMOVED=true",
				"CLEANER_STORE_CLOSE_COUNT=1");
	}

}
